/**
 * 补丁：为「关于"暗网动画"旧帖补充」处理两条评论
 * 1. 76L：清空文字，替换为指定图片
 * 2. 34L：将"帖子"设为可点击链接，跳转到「找一部在暗网上看过的离奇动画」
 * 楼层规则：楼主=1L，评论从2L起；楼层N对应升序排列的第N-2条评论。
 */
Storage.ready().then(async function () {
  var PATCH_KEY = 'darknetAnimationCommentPatch_v1';
  if (localStorage.getItem(PATCH_KEY)) return;

  var IMAGE_DATAURL = "data:image/jpeg;base64,";

  var posts = Storage.getPosts();
  var post = null;
  var target = null;
  for (var i = 0; i < posts.length; i++) {
    var t = posts[i].title || '';
    if (t.indexOf('暗网动画') !== -1 && t.indexOf('旧帖补充') !== -1) post = posts[i];
    if (t.indexOf('找一部在暗网上看过的离奇动画') !== -1) target = posts[i];
  }
  if (!post) { console.log('[补丁] 未找到「关于暗网动画旧帖补充」'); return; }
  if (!target) { console.log('[补丁] 未找到目标跳转帖子'); return; }

  var all = Storage.getComments();
  var postComments = all
    .filter(function (c) { return c.postId === post.id; })
    .sort(function (a, b) { return a.createdAt - b.createdAt; });

  // 76L -> index 74
  var c76 = postComments[74];
  if (c76) {
    c76.content = '';
    c76.images = [IMAGE_DATAURL];
  }

  // 34L -> index 32
  var c34 = postComments[32];
  if (c34 && (c34.content || '').indexOf('帖子') !== -1) {
    c34.linkTargets = [{ text: '帖子', postId: target.id }];
  }

  await Storage.saveComments(all);
  localStorage.setItem(PATCH_KEY, '1');
  console.log('[补丁] 暗网动画帖评论处理完成');
});
